from pathlib import Path
p=Path('outputs/Mechanical_Design_App/index.html');s=p.read_text(encoding='utf-8').replace('LOCAL BETA 0.6.1','LOCAL BETA 0.7')
s=s.replace('<h3>Saved project exports</h3>', '''<h3>Proposed design revision</h3><p class="muted">Export a new editable OpenSCAD revision with the current pilot diameter. This beta adapter supports M3 × 0.5 hardware, stack 3.3 mm, pocket 8 mm and boss diameter 9 mm. Only the pilot changes; this viewer stays at baseline v2.</p><button id="designExport" class="secondary">Export proposed joint revision</button><p id="designStatus" class="muted" role="status">Resolve failed checks first. Unknowns remain in the exported validation report.</p><h3>Saved project exports</h3>''')
s=s.replace("$('bom').onclick=", """$('designExport').onclick=()=>safe(async()=>{const response=await fetch('/api/design',{method:'POST',headers:{'Content-Type':'application/json','X-App-Token':token},body:JSON.stringify(payload())});if(!response.ok){const error=await response.json();$('designStatus').textContent=error.error;throw Error(error.error)}const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download='pi4-proposed-joint.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('designStatus').textContent='Exported an unvalidated proposal and hardware/check report. Baseline files and saved selections were not changed.'});
$('bom').onclick=""")
p.write_text(s,encoding='utf-8')
